function relativePath(pathA, pathB) {
  const splitPathA = pathA.split("/");
  const splitPathB = pathB.split("/");
  let commonRootIndex = 0;
  while (commonRootIndex < Math.min(splitPathA.length - 1, splitPathB.length - 1) && splitPathA[commonRootIndex] === splitPathB[commonRootIndex]) {
    commonRootIndex++;
  }
  let relativePath2 = "";
  for (let i = commonRootIndex; i < splitPathB.length - 1; i++) {
    relativePath2 += "../";
  }
  for (let i = commonRootIndex; i < splitPathA.length; i++) {
    relativePath2 += splitPathA[i] + "/";
  }
  return relativePath2.slice(0, -1);
}

