function addDonationElement(containerEl) {
  const donationEl = containerEl.createDiv({ cls: "text-format-donation" });
  const textContainerEl = donationEl.createDiv({ cls: "text-format-donation-text" });
  let qrcodeToggle;
  if ((0, import_obsidian3.getLanguage)().toLowerCase().startsWith("zh")) {
    textContainerEl.appendText("\u5982\u679C\u63D2\u4EF6\u5BF9\u60A8\u6709\u5E2E\u52A9\uFF0C\u6B22\u8FCE\u6253\u8D4F\uFF01\u{1F929} \u53EF\u4EE5\u901A\u8FC7");
    qrcodeToggle = textContainerEl.createSpan({ text: "\u5FAE\u4FE1\u3001\u652F\u4ED8\u5B9D", cls: "text-format-qrcode-toggle" });
    textContainerEl.appendText("\u3001");
    textContainerEl.createEl("a", { text: "\u26A1\uFE0F \u7231\u53D1\u7535", href: AFDIAN_URL });
    textContainerEl.appendText("\u3001");
    textContainerEl.createEl("a", { text: "\u2615\uFE0F Buy Me a Coffee", href: BUY_ME_A_COFFEE_URL });
    textContainerEl.appendText("\u8BF7\u6728\u4E00\u559D\u676F\u5496\u5561\u3002\u4E0D\u80DC\u611F\u6FC0\uFF01\u{1F647}");
  } else {
    textContainerEl.appendText("If you find this plugin useful and would like to support its development, you can sponsor me via ");
    textContainerEl.createEl("a", { text: "\u2615\uFE0F Buy Me a Coffee", href: BUY_ME_A_COFFEE_URL });
    textContainerEl.appendText(", ");
    textContainerEl.createEl("a", { text: "\u26A1\uFE0F AiFaDian", href: AFDIAN_URL });
    textContainerEl.appendText(", ");
    qrcodeToggle = textContainerEl.createSpan({ text: "WeChat or Alipay", cls: "text-format-qrcode-toggle" });
    textContainerEl.appendText(". Any amount is welcome, thank you!");
  }
  const centerEl = donationEl.createDiv({ cls: "text-format-donation-center" });
  const qrcodeEl = centerEl.createEl("img", { cls: "text-format-donation-qrcode" });
  qrcodeEl.setAttr("src", "https://s2.loli.net/2024/04/01/VtX3vYLobdF6MBc.png");
  qrcodeEl.setAttr("alt", "WeChat or Alipay donation QR code");
  qrcodeToggle.addEventListener("click", () => {
    qrcodeEl.toggleClass("is-visible", !qrcodeEl.hasClass("is-visible"));
  });
  const parser = new DOMParser();
  const coffeeLinkEl = donationEl.createEl("a", { href: BUY_ME_A_COFFEE_URL });
  coffeeLinkEl.appendChild(parser.parseFromString(buyMeACoffee, "text/xml").documentElement);
}
